var _ = Describe("SavedFunnel (coverage)", Ordered, Label("coverage"), func() {
	var (
		crClient  client.Client
		apiClient *productanalyticsfunnelsservice.ProductAnalyticsFunnelsServiceAPIService
		base      string
	)

	BeforeAll(func(ctx context.Context) {
		ensureProductAnalyticsSettingsEnabledGenerated(ctx)
		crClient = ClientsInstance.GetControllerRuntimeClient()
		apiClient = newOpenAPIClientSet().ProductAnalyticsFunnels()
		base = uniqueName("e2e-savedfunnel-cov")
	})

	for i, step := range savedFunnelCoverageSteps {
		It(fmt.Sprintf("sends step %d", i+1), Label(fmt.Sprintf("coverage-savedfunnel-%d", i+1)), func(ctx context.Context) {
			var (
				objects []client.Object
				names   []string
				ids     []string
			)
			DeferCleanup(func(ctx context.Context) {
				for _, object := range objects {
					_ = crClient.Delete(ctx, object)
				}
				for _, id := range ids {
					removeSavedFunnelGenerated(ctx, apiClient, id)
				}
			})

			for j, spec := range step {
				name := fmt.Sprintf("%s-%d-%d", base, i+1, j+1)
				cr := newSavedFunnelGenerated(name, spec)
				Expect(crClient.Create(ctx, cr)).To(Succeed())
				objects = append(objects, cr)
				names = append(names, name)
			}

			By("Waiting until every copy is synced and the API returns it")
			for _, name := range names {
				id := waitForSavedFunnelGenerated(ctx, crClient, name)
				ids = append(ids, id)
				Eventually(func(g Gomega) {
					_, httpResp, err := apiClient.FunnelsServiceGetSavedFunnel(ctx, id).Execute()
					g.Expect(cxsdk.NewAPIError(httpResp, err)).To(Succeed())
				}, time.Minute, time.Second).Should(Succeed())
			}

			By("Deleting every copy")
			for _, object := range objects {
				Expect(crClient.Delete(ctx, object)).To(Succeed())
			}
			for _, id := range ids {
				Eventually(func() bool {
					_, httpResp, err := apiClient.FunnelsServiceGetSavedFunnel(ctx, id).Execute()
					return cxsdk.IsNotFound(cxsdk.NewAPIError(httpResp, err))
				}, time.Minute, time.Second).Should(BeTrue())
			}
		})
	}
})
